import * as M from './model.js';
import * as A from './academic-year.js';
import * as P from './planner.js';
import * as Care from './classroom-care.js';
import * as Duty from './teacher-duty.js';
import * as Tutorial from './tutorial.js';
import * as Sheet from './lesson-worksheet.js';
import {REFERENCE} from './lesson-content.js';

export function createDailyUI(api){
 const {getState,setModal,commit,toast,btn,esc,portrait}=api,$=selector=>document.querySelector(selector);
 let guideMarkup='',leaveDraft={type:'early',day:null,start:900,reason:'personal',other:''};
 const reasons={personal:'개인 용무',family:'가족 일정',rest:'건강 회복',appointment:'진료 일정',other:'기타 · 직접 입력'};
 const result=(r,after)=>{if(!r||r.error){toast(r?.error||'현재 상태를 확인해 주세요.');return;}commit();after?.();};
 function work(){const s=getState(),d=Duty.data(s),slot=M.currentSlot(s),upcoming=P.data(s).entries.filter(e=>e.day===s.day&&e.start>=s.minute&&!['완료','취소','불참'].includes(e.status)&&e.type!=='task'),rows=d.work.filter(r=>r.day===s.day);
  setModal('수업 뒤의 선생님',`<p class="intro">${M.clock(s.minute)} · 16:40 퇴근까지 ${Math.max(0,1000-s.minute)}분${slot.kind==='specialist'?' · 전담시간':''}</p><div class="notice">수업이 끝나도 근무 시간은 이어집니다. 회의·공문·학생 기록·다음 수업을 준비하세요.</div><h3>남은 약속</h3>${upcoming.map(e=>`<button class="choice" data-action="planner-entry" data-id="${esc(e.id)}"><div><b>${M.clock(e.start)} ${esc(e.title)}</b><small>${M.ROOMS[e.room]?.name||'학교'} · ${esc(e.status)}</small></div></button>`).join('')||'<p>오늘 남은 확정 약속이 없습니다.</p>'}<h3>집중해서 처리할 업무</h3><label class="form-field">업무 시간<select id="duty-work-minutes">${[10,20,30].map(n=>`<option value="${n}" ${n===20?'selected':''}>${n}분</option>`).join('')}</select></label><div class="work-hub-grid">${Object.entries(Duty.WORK).map(([id,w])=>`<button class="choice" data-action="duty-perform" data-id="${id}"><div><small>${w.area}</small><b>${w.name}</b></div></button>`).join('')}</div><p class="intro">자료 검토는 공문 결재나 학생 평가 확정과 별개입니다. 실제 제출은 해당 문서에서 진행하세요.</p><div class="buttons">${btn('교사 PC','computer')}${btn('학급업무','school-life')}${btn('행정업무','admin-work')}${btn('내 일정','planner')}${btn('정리·청소','care-open')}${btn('근무·휴가','duty-open')}${s.minute>=1000?btn('퇴근하기','end-shift','','primary'):''}</div><h3>오늘 처리한 업무 · ${rows.reduce((n,r)=>n+r.end-r.start,0)}분</h3>${rows.map(r=>`<article class="notice"><b>${M.clock(r.start)}–${M.clock(r.end)} · ${Duty.WORK[r.kind].name}</b><p>${esc(r.result)}</p></article>`).join('')||'<p>업무를 마치면 시간과 결과가 기록됩니다.</p>'}`,'근무 시간 · 학급업무와 행정업무',true,{key:'teacher-work'});
 }
 function captureLeave(){if(!$('#duty-type'))return;leaveDraft={type:$('#duty-type').value,day:Number($('#duty-day').value),start:Number($('#duty-start').value),reason:$('#duty-reason').value,other:$('#duty-other').value};}
 function duty(){const s=getState(),d=Duty.data(s),days=Array.from({length:Math.max(0,Math.min(40,M.demoDays(s)-s.day))},(_,i)=>s.day+i).filter(day=>A.schoolDay(s,day)),statuses={requested:'인계 검토 대기',approved:'승인 · 사용 전',used:'사용 완료',cancelled:'취소',expired:'미사용 종료'};
  if(!days.includes(leaveDraft.day))leaveDraft.day=days[0];
  const full=Duty.TYPES[leaveDraft.type].full,start=full?520:leaveDraft.start,amount=1000-start;
  setModal('교사 근무·휴가',`<div class="duty-balances">${[['annual','연가',21],['sick','병가',7]].map(([key,label,max])=>{const b=Duty.balance(s,key);return `<article class="notice"><b>${label} ${max}일</b><strong>사용 가능 ${Duty.durationLabel(b.available)}</strong><span>사용 ${Duty.durationLabel(b.used)} · 신청/승인 ${Duty.durationLabel(b.reserved)}</span></article>`;}).join('')}</div><p class="intro">게임 규칙: 1일 = 8시간. 조퇴는 연가에서, 병조퇴는 병가에서 분 단위로 합산합니다. 학년도마다 새로 배정하며 이전 기록은 보관합니다.</p>${Duty.absent(s)?`<div class="notice">현재 휴가·조퇴 중입니다. 수업지원 교사와 방과후·늘봄 담당자에게 인계했습니다.</div><div class="buttons">${s.minute<1000?btn('인계된 하루 진행 · 16:40까지','duty-finish','','primary'):btn(s.day>=M.demoDays(s)-1?'학년도 마감':'다음 날 출근',s.day>=M.demoDays(s)-1?'week-summary':'next-day','','primary')}</div>`:''}<details id="leave-form" ${!Duty.absent(s)?'open':''}><summary>휴가·조퇴 신청</summary><div class="form-grid"><label class="form-field">종류<select id="duty-type" data-duty-field>${Object.entries(Duty.TYPES).map(([id,t])=>`<option value="${id}" ${id===leaveDraft.type?'selected':''}>${t.name}</option>`).join('')}</select></label><label class="form-field">날짜<select id="duty-day" data-duty-field>${days.map(day=>`<option value="${day}" ${day===leaveDraft.day?'selected':''}>${M.dateLabel({day})}</option>`).join('')}</select></label><label class="form-field">출발 시각<select id="duty-start" data-duty-field ${full?'disabled':''}>${Array.from({length:96},(_,i)=>520+i*5).map(t=>`<option value="${t}" ${t===(full?520:leaveDraft.start)?'selected':''}>${M.clock(t)}</option>`).join('')}</select></label><label class="form-field">용무<select id="duty-reason" data-duty-field>${Object.entries(reasons).map(([id,title])=>`<option value="${id}" ${id===leaveDraft.reason?'selected':''}>${title}</option>`).join('')}</select></label><label class="form-field layout-full" ${leaveDraft.reason==='other'?'':'hidden'}>기타 용무<input id="duty-other" maxlength="300" value="${esc(leaveDraft.other)}" placeholder="필요한 용무만 간단히 적어 주세요."></label></div><p class="notice">${M.clock(start)}–16:40 · ${Duty.durationLabel(amount)} 신청</p><div class="buttons">${btn('교감에게 신청','duty-request','','primary')}${btn('겹치는 일정 확인','planner')}</div></details><h3>신청·사용 기록</h3>${[...d.requests].reverse().map(r=>`<article class="duty-request"><b>${M.dateLabel({day:r.day})} · ${Duty.TYPES[r.type].name}</b><p>${M.clock(r.start)}–16:40 · ${Duty.durationLabel(r.minutes)} · ${statuses[r.status]}</p><p>${esc(r.reason)}</p>${r.status==='requested'?`<label class="form-switch"><input type="checkbox" id="handoff-${r.id}"><span>수업 자료·학생 출결과 남은 학생의 담당 인계를 확인했습니다.</span></label>`:''}${r.handoff?`<p class="notice">${esc(r.handoff)}</p>`:''}${r.cover.length?`<small>대체지도 ${r.cover.map(c=>c.period+'교시 '+c.subject+' ('+(c.status==='completed'?'실시 확인':'인계 계획')+')').join(' · ')}</small>`:''}<div class="buttons">${r.status==='requested'?btn('교감 검토·승인 확인','duty-approve',`data-id="${r.id}"`):''}${r.status==='approved'&&r.day===s.day?btn('인계 후 출발','duty-depart',`data-id="${r.id}"`,'primary'):''}${['requested','approved'].includes(r.status)?btn('신청 취소','duty-cancel',`data-id="${r.id}"`):''}</div></article>`).join('')||'<p>신청한 휴가가 없습니다.</p>'}<details><summary>이전 학년도 기록 ${d.history.length}개</summary>${d.history.map(y=>`<p>${y.year}학년도 · 사용 ${y.requests.filter(r=>r.status==='used').map(r=>Duty.TYPES[r.type].name+' '+Duty.durationLabel(r.minutes)).join(', ')||'없음'}</p>`).join('')}</details>`,'신청 · 인계 · 사용 시간',true,{key:'teacher-duty'});
 }
 function care(){const s=getState(),d=Care.data(s);if(!d.items.length&&s.tutorial?.practice)s.tutorial.practice.checks.clean=true;Tutorial.syncPractice(s);
  setModal('우리 교실 정리와 청소',`<div class="notice"><b>${d.items.length?'정리할 곳 '+d.items.length+'개':'깨끗한 교실'}</b><p>교실 청결 ${s.clean}/100 · 생활하면서 생긴 물건과 먼지는 정리할 때 사라집니다.</p></div><div class="care-counts">${Object.entries(Care.KINDS).map(([id,name])=>`<span>${name} <b>${d.items.filter(i=>i.type===id).length}</b></span>`).join('')}</div><h3>학생의 1인 1역</h3><p>역할이 맞는 물건을 정리합니다. 희망과 필요한 도움을 살피며, 교사가 역할을 함께 확인하면 참여가 늘어납니다.</p><div class="buttons">${btn('스스로 역할 수행','care-effort',`data-id="steady" aria-pressed="${d.effort==='steady'}"`,d.effort==='steady'?'primary':'')}${btn('함께 확인하며 열심히','care-effort',`data-id="together" aria-pressed="${d.effort==='together'}"`,d.effort==='together'?'primary':'')}${btn('역할표 변경','roles')}${btn('아침·쉬는 시간 역할 연습 · 5분','care-practice')}</div><h3>교사 마무리 청소</h3><p>학생들의 기본 정리 뒤 남은 곳을 청소합니다. 수업 후 교실에서 진행하며 근무 시간이 듭니다.</p><div class="buttons">${[[5,'주변 정리'],[10,'일반 청소'],[20,'꼼꼼한 청소']].map(([n,label])=>btn(label+' · '+n+'분','care-clean',`data-id="${n}" ${d.items.length?'':'disabled'}`)).join('')}</div><h3>최근 정리 기록</h3>${d.history.slice(-8).reverse().map(r=>`<p>${M.dateLabel({day:r.day})} ${M.clock(r.minute)} · ${r.kind==='teacher'?'교사 청소':'1인 1역'} · ${r.removed}곳 정리</p>`).join('')||'<p>아직 정리 기록이 없습니다.</p>'}`,'1인 1역 · 생활 흔적 · 교사 청소',true,{key:'classroom-care'});
 }
 function worksheet(){const s=getState(),{slot,card,row}=Sheet.current(s);if(!card){toast('과목 수업 시간에 질문지를 열 수 있어요.');return;}
  const order=[0,1,2].map(i=>(i+s.day+s.config.grade)%3);
  setModal(`${s.config.grade}학년 ${slot.subject} 질문지`,`<section class="lesson-board"><small>전자칠판 · ${esc(card.title)}</small><p>${esc(card.board)}</p></section><article class="worksheet"><p class="eyebrow">생각해 보기</p><h3>${esc(card.question)}</h3><div class="choice-list">${order.map(i=>`<button class="choice" data-action="worksheet-answer" data-id="${i}" ${!row||row.answer!==null?'disabled':''}><div><b>${esc(card.options[i])}</b></div></button>`).join('')}</div>${row?.feedback?`<p class="notice">${esc(row.feedback)}<br>함께 확인할 내용: ${esc(card.board)}</p>`:''}<label class="form-field">생각을 표현하는 방법<span>말로 설명하기 · 그림으로 나타내기 · 짝과 비교하기</span></label></article><div class="buttons">${btn(row?'이번 차시에 제시 완료':'학생에게 질문지 제시 · 5분','worksheet-issue',row?'disabled':'','primary')}${btn('수업 선택으로 돌아가기','primary')}</div><p class="intro">${row?'참여 학생 '+row.participantIds.length+'명 · '+esc(row.issued):'미리보기만으로 참여·진도·점수가 바뀌지 않습니다.'}</p><details><summary>교과 참고 자료</summary><p>${REFERENCE.name}의 교과 체계를 참고한 창작 활동입니다. 이 학교의 학년별 순서로 진행합니다.</p><a href="${REFERENCE.url}" target="_blank" rel="noopener">교육부 교육과정 고시</a></details>`,'수업 목표 · 발문 · 피드백',true,{key:'lesson-worksheet'});
 }
 function renderGuide(){const s=getState(),step=Tutorial.currentPractice(s),host=$('#practice-guide');if(!host)return;
  for(const el of document.querySelectorAll('.tutorial-target'))el.classList.remove('tutorial-target');
  host.hidden=!step;if(!step){guideMarkup='';return;}const p=s.tutorial.practice,count=Tutorial.PRACTICE.filter(t=>p.checks[t.id]).length;
  const markup=`<div><b>직접 해 보기 ${count+1}/${Tutorial.PRACTICE.length} · ${esc(step.title)}</b>${p.collapsed?'':`<p>${esc(step.hint)}</p>`}</div><div class="buttons">${btn('해 보기','practice-go','','primary')}${btn(p.collapsed?'펼치기':'접기','practice-toggle')}${btn('건너뛰기','practice-skip')}</div>`;
  if(markup!==guideMarkup){host.innerHTML=markup;guideMarkup=markup;}
  if(!$('#modal').open){const target=[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===step.action&&!host.contains(el));target?.classList.add('tutorial-target');}
 }
 function handle(action,id,el){const s=getState();
  if(action==='practice-start'){Tutorial.startPractice(s);api.close();commit();return;}
  if(action==='practice-go'){const step=Tutorial.currentPractice(s);if(step)api.handle(step.action);return;}
  if(action==='practice-toggle'){s.tutorial.practice.collapsed=!s.tutorial.practice.collapsed;commit();return;}
  if(action==='practice-skip'){s.tutorial.practice.status='skipped';commit();return;}
  if(action==='duty-finish'){if(Duty.absent(s)){M.advance(s,1000-s.minute);commit();duty();}return;}
  if(action==='duty-work'){work();return;}if(action==='duty-open'){duty();return;}
  if(action==='duty-perform'){result(Duty.perform(s,id,Number($('#duty-work-minutes').value)),work);return;}
  if(action==='duty-request'){captureLeave();result(Duty.requestLeave(s,{...leaveDraft,reason:leaveDraft.reason==='other'?leaveDraft.other:reasons[leaveDraft.reason]}),duty);return;}
  if(action==='duty-approve'){result(Duty.approve(s,id,$('#handoff-'+id)?.checked),duty);return;}
  if(action==='duty-cancel'){result(Duty.cancel(s,id),duty);return;}
  if(action==='duty-depart'){result(Duty.depart(s,id),duty);return;}
  if(action==='care-open'){care();return;}if(action==='care-effort'){Care.setEffort(s,id);commit();care();return;}
  if(action==='care-practice'){result(Care.practice(s),care);return;}
  if(action==='care-clean'){result(Care.clean(s,Number(id)),care);return;}
  if(action==='worksheet-open'){worksheet();return;}
  if(action==='worksheet-issue'){result(Sheet.issue(s),()=>{const {card,row}=Sheet.current(s),student=s.students.find(st=>row?.participantIds.includes(st.id));worksheet();if(student)api.speak(student.id,card.question,student.name);});return;}
  if(action==='worksheet-answer'){result(Sheet.answer(s,Number(id)),worksheet);return;}
 }
 document.addEventListener('change',e=>{if(e.target.matches('[data-duty-field]')){captureLeave();duty();}});
 document.addEventListener('input',e=>{if(e.target.id==='duty-other')leaveDraft.other=e.target.value;});
 return {work,duty,care,worksheet,renderGuide,handle};
}
